def to_bits(chars):
    # Uppercase is '1', lowercase is '0'
    return ["1" if c.isupper() else "0" for c in chars]

def to_bytestr(bits):
    # Group bits by 8
    return [bits[i:i+8] for i in range(0, len(bits), 8)]

def bin_to_chr(b):
    try:
        return chr(int("".join(b), 2))
    except:
        return '?'  # In case of bad bits

def decode_file(fname, path):
    chars = get_alpha_chars(path)
    bits = to_bits(chars)
    byte_groups = to_bytestr(bits)
    decoded = ''.join([bin_to_chr(b) for b in byte_groups])
    return decoded

